contracts.definition:
export interface SourceRange {
  start: number;
  end: number;
}

export interface ParsedDeclaration extends SourceRange {
  name: string;
  fqcn: string;
  kind: PhpSymbolKind;
  anonymous: boolean;
  declarationStart: number;
  declarationEnd: number;
  extendsNames: string[];
  implementsNames: string[];
  traitNames: string[];
  traitUses?: Array<SourceRange & { names: string[] }>;
  attributeNames?: string[];
  attributeMarkers?: Array<{ name: string; arguments?: string }>;
  traitAdaptations: ParsedTraitAdaptation[];
  readonlyClass: boolean;
  abstractClass: boolean;
  finalClass?: boolean;
  enumBackingType?: 'int' | 'string';
}

export interface ParsedCallableDeclaration extends SourceRange {
  name: string;
  fqcn: string;
  kind: 'function' | 'method';
  containerFqcn?: string;
  parameters: ParsedParameter[];
  returnType?: string;
  /** Parser-native return type before any downstream PHPDoc refinement. */
  nativeReturnType?: string;
  declarationStart: number;
  declarationEnd: number;
  visibility: 'public' | 'protected' | 'private';
  static: boolean;
  finalMethod?: boolean;
}

export interface ParsedPhpDocument {
  namespace: string;
  declarations: ParsedDeclaration[];
  callables: ParsedCallableDeclaration[];
  assignments: ParsedAssignment[];
  scopes: ParsedScope[];
  variableReferences: ParsedVariableReference[];
  returns: ParsedReturnStatement[];
  narrowings: ParsedTypeNarrowing[];
  properties: ParsedPropertyDeclaration[];
  constants: ParsedConstantDeclaration[];
  imports: ParsedImport[];
  typeReferences: ParsedTypeReference[];
  rawNames: RawName[];
  memberAccesses: ParsedMemberAccess[];
  calls: ParsedCall[];
  errors: SourceRange[];
  commentRanges: SourceRange[];
  stringRanges: SourceRange[];
  tree: Tree;
}

export type PreparedPhpDocument = (
  | { kind: 'full'; facts: Omit<ParsedPhpDocument, 'tree'>; controlFlowAssignments: number[] }
  | { kind: 'declarations'; facts: Omit<ParsedPhpDeclarationDocument, 'tree'>; controlFlowAssignments: [] }
) & { namespaceScopes?: ParsedNamespaceScope[] };

export interface DocumentSnapshot {
  uri: string;
  version: number | null;
  length: number;
  textHash?: string;
}

export interface PlannedTextEdit {
  uri: string;
  start: number;
  end: number;
  newText: string;
  expectedVersion: number | null;
  expectedLength: number;
  expectedTextHash?: string;
}

export type PlannedFileOperation =
  | { kind: 'create'; uri: string; overwrite?: boolean }
  | { kind: 'rename'; oldUri: string; newUri: string; overwrite?: boolean }
  | { kind: 'delete'; uri: string; recursive?: boolean };

export interface EditPlan {
  schema: 1;
  label: string;
  textEdits: PlannedTextEdit[];
  fileOperations: PlannedFileOperation[];
}

export interface SemanticFileSnapshot {
  uri: string;
  source: string;
  namespace: string;
  declarations: ParsedDeclaration[];
  callables: ParsedCallableDeclaration[];
  imports: ParsedImport[];
  typeReferences: ParsedTypeReference[];
  assignments: ParsedAssignment[];
  properties: ParsedPropertyDeclaration[];
  constants: ParsedConstantDeclaration[];
  rawNames: RawName[];
  memberAccesses: ParsedMemberAccess[];
  calls: ParsedCall[];
  scopes: ParsedScope[];
  variableReferences: ParsedVariableReference[];
  returns: ParsedReturnStatement[];
  narrowings: ParsedTypeNarrowing[];
  templates: SemanticTemplate[];
  genericParents: SemanticGenericParent[];
  mixins: SemanticMixin[];
  magicMembers: SemanticMagicMember[];
  syntaxErrors: SourceRange[];
  commentRanges: SourceRange[];
  stringRanges: SourceRange[];
}

export interface SemanticDeclarationSnapshot {
  uri: string;
  namespace: string;
  declarations: ParsedDeclaration[];
  callables: ParsedCallableDeclaration[];
  properties: ParsedPropertyDeclaration[];
  constants: ParsedConstantDeclaration[];
  imports: ParsedImport[];
  templates: SemanticTemplate[];
  genericParents: SemanticGenericParent[];
  mixins: SemanticMixin[];
  magicMembers: SemanticMagicMember[];
}

export interface SemanticSourceDeclarationSnapshot {
  schema: 7;
  source: string;
  declaration: SemanticDeclarationSnapshot;
}

export interface SemanticImplementationSnapshot {
  uri: string;
  source: string;
  file: SemanticImplementationFacts;
  callables: SemanticCallableImplementationRecord[];
}

export interface SemanticSnapshot {
  schema: 89;
  layers: {
    referenceCandidates: { indexed: boolean; keys: string[] };
    typeDependencies: { indexed: boolean; nodes: Array<{ key: string; dependencies: string[] }> };
  };
  declaration: SemanticDeclarationSnapshot;
  implementation: SemanticImplementationSnapshot;
}

export interface SemanticUpdateResult {
  incremental: boolean;
  changedRanges: number;
  /** The broadest semantic layer changed by this update. */
  kind: SemanticUpdateKind;
  /** Stable lowercase callable identities whose implementation may have changed. */
  changedCallables: string[];
  /** Stable lowercase type identities whose declaration surface may have changed. */
  changedTypes: string[];
}

export interface ProjectIndexOptions { onProgress?: (progress: IndexProgress) => void; limits?: ProjectIndexLimits; shouldContinue?: () => boolean; uriForPath?: (path: string) => string; onSource: (source: IndexedSource) => unknown | Promise<unknown>; prepareSource?: (source: IndexedSource) => unknown | Promise<unknown>;
  /** Hash every cached source before restoring facts, even when file metadata is unchanged. */
  verifyCachedSourceHash?: boolean;
  /** Use only with a conservative, complete source prefilter. */
  skipSource?: (path: string, info: { size: number; mtimeMs: number; ctimeMs: number }) => boolean;
  /** Charge only candidate files to read budgets; inspect at most 50,000 PHP paths by default. Requires skipSource. */
  skipSourceOutsideBudget?: boolean;
  /** Optional bounded inspector. It may supply current source text to avoid a second read. Failures make the scan incomplete. */
  inspectSource?: (path: string) => Promise<{ size: number; mtimeMs: number; ctimeMs: number; source?: string }>;
  onProjectComplete?: () => unknown | Promise<unknown>; includeDependencies?: boolean; yieldEvery?: number; readConcurrency?: number; cache?: ProjectIndexCacheOptions; project?: ComposerProject; }

export type PhpType =
  | { kind: 'primitive'; name: PrimitiveName }
  | { kind: 'named'; name: string }
  | { kind: 'literal'; value: string | number | boolean }
  | { kind: 'integer-range'; min: number | null; max: number | null }
  | { kind: 'class-string'; of?: PhpType }
  | { kind: 'list'; valueType: PhpType; nonEmpty: boolean }
  | { kind: 'array'; keyType: PhpType; valueType: PhpType; nonEmpty: boolean }
  | { kind: 'shape'; fields: ShapeField[]; sealed: boolean }
  | { kind: 'generic'; base: PhpType; arguments: PhpType[] }
  | { kind: 'callable'; parameters: CallableParameter[]; returnType: PhpType }
  | { kind: 'union'; types: PhpType[] }
  | { kind: 'intersection'; types: PhpType[] }
  | { kind: 'unknown'; reason?: string };

export interface PhpRuntime {
  command: string;
  path: string;
  version: string;
  versionId: number;
  minor: string;
  sapi: string;
  loadedExtensions: string[];
  availableFunctions?: string[];
  readlineLib?: string;
  intlCharConstants?: IntlCharRuntimeConstants;
  intlCalendarFieldCount?: number;
  intlCurrencyAccountingAvailable?: boolean;
  zipRuntime?: ZipRuntimeFacts;
  zlibRuntime?: ZlibRuntimeFacts;
  socketsRuntime?: SocketsRuntimeFacts;
  pcntlRuntime?: PcntlRuntimeFacts;
  pgsqlRuntime?: PgsqlRuntimeFacts;
  xslRuntime?: XslRuntimeFacts;
  redisRuntime?: RedisRuntimeFacts;
  imagickRuntime?: ImagickRuntimeFacts;
  curlRuntime?: CurlRuntimeFacts;
  gdRuntime?: GdRuntimeFacts;
  tokenizerRuntime?: TokenizerRuntimeFacts;
  apcuRuntime?: ApcuRuntimeFacts;
  openSslRuntime?: OpenSslRuntimeFacts;
  mysqliRuntime?: MysqliRuntimeFacts;
  pdoRuntime?: PdoRuntimeFacts;
  sodiumRuntime?: SodiumRuntimeFacts;
  pcreRuntime?: PcreRuntimeConstants;
  sysvMsgConstants?: SysvMsgRuntimeConstants;
  posixConstants?: PosixRuntimeConstants;
  mbOnigurumaVersion?: string;
  getrusageRuntime?: GetrusageRuntimeFacts;
  loadedConfigurationFile?: string;
  scannedConfigurationFiles: string[];
}

export interface SemanticProviderDescriptor {
  providerId: string;
  command: string;
  args?: readonly string[];
  timeoutMs?: number;
  maxOutputBytes?: number;
  requiresProjectTypes?: boolean;
  acceptsDocumentSnapshots?: boolean;
  replacesContainerServices?: boolean;
  requiresContainerServices?: boolean;
  replacesEventRelations?: boolean;
  replacesControllerContexts?: boolean;
}

export interface SemanticProviderRequest {
  protocolVersion: typeof SEMANTIC_PROVIDER_PROTOCOL_VERSION;
  id: string;
  method: 'facts';
  params: { rootUri: string; rootPath: string; generation: string; phpVersion: string; environment?: string;
    documents?: readonly SemanticProviderDocument[]; projectTypes?: readonly SemanticProviderProjectType[];
    containerServices?: readonly ExternalContainerServiceFact[] };
}

export interface SemanticProviderResponse {
  protocolVersion: typeof SEMANTIC_PROVIDER_PROTOCOL_VERSION;
  id: string;
  result?: SemanticFactsContribution;
  error?: { code: string; message: string };
}

export interface SemanticFactsContribution {
  schema: typeof SEMANTIC_FACTS_SCHEMA;
  providerId: string;
  generation: string;
  complete: boolean;
  methods: readonly ExternalMethodFact[];
  properties: readonly ExternalPropertyFact[];
  literalMethodReturns: readonly ExternalLiteralMethodReturnFact[];
  containerServices?: readonly ExternalContainerServiceFact[];
  containerParameters?: readonly ExternalContainerParameterFact[];
  containerMethodArguments?: readonly ExternalContainerMethodArgumentFact[];
  containerPropertyArguments?: readonly ExternalContainerPropertyArgumentFact[];
  containerConfigurationUris?: readonly string[];
  /** Attempted file inputs from an authoritative container provider, including absent paths. */
  containerInputUris?: readonly string[];
  containerInputEvidenceComplete?: boolean;
  eventSubscriptions?: readonly ExternalEventSubscriptionFact[];
  eventDispatches?: readonly ExternalEventDispatchFact[];
  controllerContexts?: readonly ControllerTemplateContext[];
}

export interface RouteProviderRequest {
  protocolVersion: typeof ROUTE_PROVIDER_PROTOCOL_VERSION;
  id: string;
  method: 'routes';
  params: { rootUri: string; rootPath: string; generation: string; phpVersion: string; environment?: string; documents?: readonly RouteProviderDocument[] };
}

export interface RouteFactsContribution {
  schema: typeof ROUTE_FACTS_SCHEMA;
  providerId: string;
  generation: string;
  complete: boolean;
  routes: readonly RouteFact[];
  /** Attempted file inputs, including paths that did not exist. */
  inputUris?: readonly string[];
  /** Directories enumerated while expanding wildcard and attribute imports. */
  inputDirectoryUris?: readonly string[];
  inputEvidenceComplete?: boolean;
}

export interface RouteProviderResponse {
  protocolVersion: typeof ROUTE_PROVIDER_PROTOCOL_VERSION;
  id: string;
  result?: RouteFactsContribution;
  error?: { code: string; message: string };
}

export interface PhpCompanionIntegrationContribution {
  integrationId: string;
  semanticProviders?: readonly SemanticProviderDescriptor[];
  routeProviders?: readonly RouteProviderDescriptor[];
}

export interface PhpCompanionPluginRegistration {
  /** Atomically replace this integration without exposing a withdrawn interval. */
  update?(contribution: PhpCompanionIntegrationContribution): void;
  dispose(): void;
}

export interface PhpCompanionPluginApi {
  version: typeof PHP_COMPANION_PLUGIN_API_VERSION;
  registerIntegration(contribution: PhpCompanionIntegrationContribution): PhpCompanionPluginRegistration;
  /** Send a namespaced feature request through the core language-server lifecycle. Added compatibly to API v1. */
  requestLanguageServer?<T>(method: string, params: unknown): Promise<T>;
}

export interface InteropHello {
  protocolVersion: typeof INTEROP_PROTOCOL_VERSION;
  providerId: string;
  projectId: string;
  snapshotVersion: string;
  capabilities: InteropCapability[];
}

export type SerializedPhpType =
  | { kind: 'unknown'; reason?: string }
  | { kind: 'primitive'; name: 'bool' | 'int' | 'float' | 'string' | 'array' | 'object' | 'callable' | 'iterable' | 'resource' | 'null' | 'void' | 'never' | 'mixed' }
  | { kind: 'named'; name: string }
  | { kind: 'union' | 'intersection'; types: SerializedPhpType[] };
